      mainContent: `
## The Framework

The Mandukya doesn't just map consciousness. It implies **you can optimize each state.**

Here's how:

## Hacking Waking State (Vaishvanara)

**Goal:** Full presence with sensory reality. No mental fog.

**Signs it needs optimization:**
- You're physically present but mentally elsewhere
- Constant distraction
- Can't focus on one thing
- Everything feels flat

**Hacks:**

### 1. Sensory Anchoring (30 seconds)

Before any task:
- Name 5 things you see
- Name 4 things you feel (texture, temperature)
- Name 3 things you hear
- Name 2 things you smell
- Name 1 thing you taste

Instantly pulls you into waking state.

### 2. Single-Tasking Sprints

Set a timer for 25 minutes.
Do ONE thing. Nothing else.
Resist every impulse to switch.

This trains waking-state concentration.

### 3. Digital Detox Rituals

First hour of the day: no phone.
Last hour of the day: no screens.

Screens fragment attention. You need unbroken waking-state time.

## Hacking Dream State (Taijasa)

**Goal:** Make internal narrative CONSCIOUS and CREATIVE, not compulsive and destructive.

**Signs it needs optimization:**
- Stuck in worry loops
- Constant rehearsing of past conversations
- Catastrophizing about the future
- Can't turn off mental chatter

**Hacks:**

### 1. Thought Labeling (throughout the day)

When you notice you're in mental narrative, silently label it:
- "Planning"
- "Worrying"
- "Replaying"
- "Fantasizing"

Labeling creates distance. You shift from "I am anxious" to "There's anxious narrative."

### 2. Scheduled Worry Time

Set aside 15 minutes.
Worry INTENTIONALLY.
Write down every concern.
When the timer ends, STOP.

This contains dream-state rumination instead of letting it bleed everywhere.

### 3. Creative Dreaming vs Destructive Dreaming

**Ask:** "Is this mental narrative SERVING me?"

- Planning dinner = useful dreaming
- Imagining a project = useful dreaming
- Replaying an argument for the 10th time = destructive dreaming
- Catastrophizing about unlikely scenarios = destructive dreaming

When you catch destructive dreaming: **Label it, then redirect attention to something real (sensation, breath).**

## Hacking Deep Sleep State (Prajna)

**Goal:** Access genuine rest and restoration, not just collapse-from-exhaustion.

**Signs it needs optimization:**
- You sleep 8 hours and wake up tired
- Can't quiet your mind before sleep
- Restless sleep, lots of dreaming
- Waking up in thought-loops

**Hacks:**

### 1. Wind-Down Ritual (1 hour before sleep)

- Dim lights (signal to body: time to rest)
- No arguments or intense content
- Gentle activity (stretching, journaling, tea)
- Transition from waking/dreaming to preparation for deep sleep

### 2. Yoga Nidra

A guided practice that induces deep-sleep-like states while awake.

Find a 20-minute recording.
Do it before bed.

Trains your nervous system to ACCESS deep rest consciously.

### 3. Sleep Mantra

As you're falling asleep, mentally repeat:

**"I release. I release. I release."**

Don't hold any thoughts. Don't solve any problems. Just release.

## Hacking Turiya (The Witness)

**Goal:** Stabilize as the unchanging awareness beneath all three states.

**Signs it needs optimization:**
- You're constantly identified with thoughts/emotions
- No gap between stimulus and reaction
- Life feels overwhelming
- You can't access peace

**Hacks:**

### 1. Noting Practice (throughout the day)

Every hour, pause for 30 seconds:
- "Aware of thinking"
- "Aware of feeling"
- "Aware of sensing"

Don't change anything. Just note that awareness is present.

### 2. The Gap Practice

Throughout the day, notice gaps:
- Gap between thoughts
- Gap between breaths
- Gap between words someone speaks
- Gap between tasks

**The gap is where turiya is obvious.** You can't be identified when there's nothing to identify with.

### 3. Morning Witness Meditation (10 minutes)

Sit. Don't do anything.

Just notice: **"I'm aware."**

Not "aware of X." Just "aware."

Let everything arise and pass.
You remain.

That's turiya.

## Integration: The Full Stack

**Morning:** 10 minutes witness meditation (turiya)
**Throughout day:** Sensory anchoring for waking, thought labeling for dreaming, gap awareness for turiya
**Evening:** Wind-down ritual for deep sleep
**Before bed:** OM chanting (moving through all states)

You're now CONSCIOUSLY NAVIGATING consciousness instead of being tossed around by it.
      `,
      keyTakeaway: 'Each state of consciousness can be optimized: waking (full presence), dreaming (conscious narrative), deep sleep (true rest), turiya (stable witness).',
