        options: [
          'Witnessing means feeling the emotion fully while maintaining awareness that you are not the emotion',
          'Suppressing means hiding it from others; witnessing means expressing it fully',
          'Witnessing means analyzing why you feel it; suppressing means ignoring it',
          'Suppressing is unconscious; witnessing is thinking about the emotion'
        ],
